coreBehaviorDefinitions.typescript:
export function importBankCsv(
  db: Database,
  companyRoot: string,
  csvPath: string,
  options: ImportBankCsvOptions = {},
): BankImportResult {
  // ===== BANK CLUSTER (#187) =====
  // Resolve the target account up front: new imports couple their rows to a
  // bank account. A given-but-unknown account aborts before any parsing.
  let bankAccount: BankAccount | null = null;
  if (options.account !== undefined && String(options.account).trim() !== "") {
    bankAccount = resolveBankAccount(db, options.account);
    if (!bankAccount) return { ok: false, errors: [`bank account '${options.account}' does not exist`] };
    if (!bankAccount.active) return { ok: false, errors: [`bank account '${bankAccount.slug}' is inactive and cannot receive imports`] };
  }
  const bankAccountId = bankAccount?.id ?? null;
  // ===== END BANK CLUSTER (#187) =====

  if (!existsSync(csvPath)) return { ok: false, errors: [`file does not exist: ${csvPath}`] };

  // ===== BANK CLUSTER (#186) =====
  // A named profile pins delimiter / encoding / date order and an explicit
  // column->field map. A given-but-unknown profile aborts before parsing.
  let profile: BankImportProfile | null = null;
  if (options.profile !== undefined && String(options.profile).trim() !== "") {
    profile = getBankProfile(String(options.profile));
    if (!profile) {
      return { ok: false, errors: [`unknown bank import profile '${options.profile}' (known: ${listBankProfileNames().join(", ")})`] };
    }
  }
  // ===== END BANK CLUSTER (#186) =====

  const fileBytes = readFileSync(csvPath);
  const sourceFileHash = sha256Bytes(fileBytes);
  const importBatchId = `BANK-${new Date().toISOString().replace(/[-:TZ.]/g, "").slice(0, 14)}-${sourceFileHash.slice(0, 8)}`;

  // ===== BANK CLUSTER (#186) =====
  // With a profile the file is parsed under the pinned format; without one the
  // generic alias-guessing parser is used unchanged.
  let rows: BankImportRow[];
  if (profile) {
    const parsed = parseCsvWithProfile(fileBytes, profile);
    if (parsed.errors.length > 0) return { ok: false, errors: parsed.errors };
    rows = parsed.rows;
  } else {
    const parsedCsv = parseCsv(fileBytes.toString("utf8"));
    if (parsedCsv.errors.length > 0) return { ok: false, errors: parsedCsv.errors };
    rows = parsedCsv.rows.map(toRow);
  }
  // ===== END BANK CLUSTER (#186) =====
  const validation = validateBankImportRows(rows);
  if (!validation.ok) return { ok: false, errors: validation.errors };

  const p = companyPaths(companyRoot);
  mkdirSync(p.bankProcessed, { recursive: true });
  copyFileSync(csvPath, join(p.bankProcessed, `${importBatchId}-${basename(csvPath)}`));

  let imported = 0;
  let skippedDuplicates = 0;
  const skippedDuplicateRows: string[] = [];
  const importedRowIds: number[] = [];
  // Per-content-fingerprint counter: distinguishes repeated identical rows
  // within this file so each gets a unique transaction_hash.
  const occurrenceByContent = new Map<string, number>();
  const insert = db.prepare(
    `INSERT INTO bank_transactions (
      transaction_date, booking_date, text, amount, currency, reference, amount_dkk, fx_rate_to_dkk,
      source_file_hash, import_batch_id, transaction_hash, status, retain_until,
      bank_account_id, counterparty_name, counterparty_account, message, archive_reference, customer_reference, balance_after, raw_json
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'imported', ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  );

  db.transaction(() => {
    for (const row of rows) {
      const contentHash = transactionFingerprint(row, 0, bankAccountId);
      const occurrence = occurrenceByContent.get(contentHash) ?? 0;
      occurrenceByContent.set(contentHash, occurrence + 1);
      const hash = transactionFingerprint(row, occurrence, bankAccountId);
      const existing = db.query("SELECT id FROM bank_transactions WHERE transaction_hash = ?").get(hash) as { id: number } | null;
      if (existing) {
        skippedDuplicates += 1;
        skippedDuplicateRows.push(`${row.transactionDate} ${row.text.trim()} ${normalizeAmount(row.amount)} ${normalizeCurrency(row.currency)}`);
        continue;
      }
      const result = insert.run(
        row.transactionDate,
        row.bookingDate ?? null,
        row.text.trim(),
        normalizeAmount(row.amount),
        normalizeCurrency(row.currency),
        row.reference ?? null,
        normalizeAmountOrNull(row.amountDkk),
        row.fxRateToDkk == null ? null : roundRate6(row.fxRateToDkk),
        sourceFileHash,
        importBatchId,
        hash,
        retainUntilForDate(db, row.bookingDate ?? row.transactionDate),
        bankAccountId,
        row.counterpartyName?.trim() || null,
        row.counterpartyAccount?.trim() || null,
        row.message?.trim() || null,
        row.archiveReference?.trim() || null,
        row.customerReference?.trim() || null,
        row.balanceAfter == null ? null : normalizeAmount(row.balanceAfter),
        row.raw ? JSON.stringify(row.raw) : null,
      );
      importedRowIds.push(Number(result.lastInsertRowid));
      imported += 1;
    }
    insertAuditLog(db, {
      eventType: "bank_import",
      entityType: "bank_transaction_batch",
      entityId: importBatchId,
      message: `Imported ${imported} bank transactions from ${basename(csvPath)}; skipped ${skippedDuplicates} duplicates`,
    });
  })();

  // ===== BANK CLUSTER (#189) =====
  // When a profile supplied a running balance, verify continuity across the
  // freshly-imported batch. A break is surfaced (warning + exception) but never
  // fails the import — a partial export is a legitimate input.
  const balanceCheck = verifyBatchBalanceContinuity(db, importedRowIds);
  // ===== END BANK CLUSTER (#189) =====

  return {
    ok: true,
    importBatchId,
    imported,
    skippedDuplicates,
    skippedDuplicateRows,
    sourceFileHash,
    bankAccountId: bankAccountId ?? undefined,
    bankAccountSlug: bankAccount?.slug,
    profile: profile?.name,
    ...balanceCheck,
    errors: [],
  };
}

export function syncUnmatchedBankTransactionExceptions(db: Database) {
  // Every bank transaction with no posted journal entry — together with its
  // currently-open UNMATCHED_BANK_TRANSACTION exception (if any). A new
  // transaction has no exception yet; one synced before its bilag was ingested
  // has a stale one. Both are handled below: missing ⇒ create, stale ⇒ the old
  // exception is resolved and a fresh, corrected one opened in its place.
  const unmatchedRows = db.query(
    `SELECT bt.id, bt.transaction_date, bt.booking_date, bt.text, bt.amount, bt.currency, bt.reference, bt.import_batch_id,
            ex.id AS exception_id, ex.message AS exception_message, ex.required_action AS exception_required_action
     FROM bank_transactions bt
     LEFT JOIN bank_journal_reconciliations br ON br.bank_transaction_id = bt.id
     LEFT JOIN exceptions ex
       ON ex.related_bank_transaction_id = bt.id
      AND ex.type = 'UNMATCHED_BANK_TRANSACTION'
      AND ex.status = 'open'
     WHERE br.journal_entry_id IS NULL
     ORDER BY bt.transaction_date ASC, bt.id ASC`
  ).all() as Array<any>;

  let created = 0;
  let refreshed = 0;
  let resolvedStale = 0;
  for (const row of unmatchedRows) {
    const amount = Number(row.amount);
    const bilag = findCandidateBilag(db, row.id, amount);
    const { message, requiredAction } = describeUnmatchedBankTransaction(
      {
        id: row.id,
        transaction_date: row.transaction_date,
        text: row.text,
        amount,
        currency: row.currency,
      },
      bilag,
    );
    const sourceEvidence = JSON.stringify({
      bankTransactionId: row.id,
      transactionDate: row.transaction_date,
      bookingDate: row.booking_date,
      text: row.text,
      amount,
      currency: row.currency,
      reference: row.reference,
      importBatchId: row.import_batch_id,
      candidateBilagId: bilag?.documentId ?? null,
      candidateBilagNo: bilag?.documentNo ?? null,
    });

    if (row.exception_id != null) {
      // An exception already exists. When its Danish text is still current
      // there is nothing to do — leaving it untouched keeps the sync
      // idempotent, so re-importing overlapping bank rows never touches the
      // immutable row.
      const stale =
        row.exception_message !== message ||
        (row.exception_required_action ?? "") !== requiredAction;
      if (!stale) continue;

      // The text has gone stale — typically because the matching bilag has
      // since been ingested, so the generic "no bilag found" message can now
      // name the bilag. Exception rows are append-only (the immutability
      // trigger rejects ANY mutation, including a corrected message or a
      // newly-linked related_document_id), so we cannot rewrite the row.
      // Instead we resolve the stale exception and fall through to open a
      // fresh, corrected one — the audit chain stays intact and we stay
      // within the existing open → resolved lifecycle.
      resolveException(db, {
        id: row.exception_id,
        note: "Erstattet automatisk: beskrivelsen blev opdateret, da et passende bilag blev tilføjet bogføringen",
        resolvedBy: "system:sync-unmatched-bank-transactions",
      });
      refreshed += 1;
      resolvedStale += 1;
      // fall through — recordException below opens the corrected exception.
    }

    const result = recordException(db, {
      type: "UNMATCHED_BANK_TRANSACTION",
      severity: "medium",
      relatedBankTransactionId: row.id,
      relatedDocumentId: bilag?.documentId ?? null,
      message,
      requiredAction,
      sourceEvidence: JSON.parse(sourceEvidence),
      postingPreview: {
        bankTransactionId: row.id,
        candidateBilagId: bilag?.documentId ?? null,
      },
    });
    if (result.ok && !result.duplicate) created += 1;
  }

  return { ok: true, created, refreshed, resolvedStale, errors: [] };
}

export function removePathWithRetry(path: string, options: RmOptions = { recursive: true, force: true }): void {
  retryTransientCleanup(() => rmSync(path, options));
}

transitiveLocalBehaviorDefinitions.typescript:
export function resolveBankAccount(db: Database, idOrSlug: string | number): BankAccount | null {
  const asNumber = typeof idOrSlug === "number" ? idOrSlug : Number(idOrSlug);
  const byId = Number.isInteger(asNumber) && asNumber > 0
    ? db.query("SELECT * FROM bank_accounts WHERE id = ?").get(asNumber)
    : null;
  if (byId) return mapBankAccountRow(byId);
  const slug = String(idOrSlug).trim();
  const bySlug = slug ? db.query("SELECT * FROM bank_accounts WHERE slug = ?").get(slug) : null;
  return bySlug ? mapBankAccountRow(bySlug) : null;
}

function sha256Bytes(data: Uint8Array | string) {
  return createHash("sha256").update(data).digest("hex");
}

function normalizeAmount(value: unknown) {
  return typeof value === "number" && Number.isFinite(value) ? roundDkk(value) : NaN;
}

function parseCsv(content: string): CsvParseResult {
  const records = tokenizeLogicalCsvRecords(content);
  if (records.length === 0) return { rows: [], errors: [] };

  const delimiter = detectDelimiter(records[0].text);
  const headerParsed = parseCsvLine(records[0].text, delimiter);
  const header = headerParsed.values.map(canonicalHeader);
  const errors: string[] = [];
  if (headerParsed.unterminatedQuote) errors.push("CSV header has unterminated quoted field");
  // Two source columns must not canonicalise to the same key, otherwise the
  // row object silently keeps only the rightmost column (last wins).
  const seenHeaders = new Set<string>();
  for (const key of header) {
    if (seenHeaders.has(key)) {
      errors.push(`CSV header has duplicate canonical column: ${key}`);
    }
    seenHeaders.add(key);
  }
  for (const required of REQUIRED_COLUMNS) {
    if (!header.includes(required)) {
      errors.push(`CSV header missing required column: ${required} (accepted: ${HEADER_ALIASES[required].join(", ")})`);
    }
  }

  const rows: Record<string, string>[] = [];
  for (const record of records.slice(1)) {
    const parsed = parseCsvLine(record.text, delimiter);
    if (parsed.unterminatedQuote) errors.push(`CSV row ${record.startLine} has unterminated quoted field`);
    if (parsed.values.length !== header.length) {
      errors.push(`CSV row ${record.startLine} has ${parsed.values.length} fields, header has ${header.length}`);
      continue;
    }
    const row: Record<string, string> = {};
    header.forEach((key, idx) => {
      row[key] = parsed.values[idx] ?? "";
    });
    rows.push(row);
  }
  return { rows, errors };
}

function normalizeAmountOrNull(value: unknown) {
  if (value === undefined || value === null) return null;
  const normalized = normalizeAmount(value);
  return Number.isFinite(normalized) ? normalized : null;
}

export function parseCsvWithProfile(bytes: Uint8Array, profile: BankImportProfile): ProfileParseResult {
  const content = decodeForProfile(bytes, profile.encoding);
  const records = tokenizeLogicalCsvRecords(content);
  if (records.length === 0) return { rows: [], errors: [] };

  const headerParsed = parseCsvLine(records[0].text, profile.delimiter);
  const errors: string[] = [];
  if (headerParsed.unterminatedQuote) errors.push("CSV header has unterminated quoted field");

  // Map each header column index to the canonical field the profile assigns.
  const columnField: (ProfileFieldName | null)[] = headerParsed.values.map((header) => {
    const key = normalizeHeader(header).replace(/_/g, " ");
    return profile.columns[key] ?? null;
  });
  for (const required of ["transaction_date", "text", "amount"] as const) {
    if (!columnField.includes(required)) {
      errors.push(`profile '${profile.name}' could not map a column to required field: ${required}`);
    }
  }
  if (errors.length > 0) return { rows: [], errors };

  const rows: BankImportRow[] = [];
  for (const record of records.slice(1)) {
    const parsed = parseCsvLine(record.text, profile.delimiter);
    if (parsed.unterminatedQuote) errors.push(`CSV row ${record.startLine} has unterminated quoted field`);
    if (parsed.values.length !== headerParsed.values.length) {
      errors.push(`CSV row ${record.startLine} has ${parsed.values.length} fields, header has ${headerParsed.values.length}`);
      continue;
    }
    const fields: Partial<Record<ProfileFieldName, string>> = {};
    const raw: Record<string, string> = {};
    headerParsed.values.forEach((header, idx) => {
      raw[header] = parsed.values[idx] ?? "";
      const field = columnField[idx];
      // First non-empty wins (e.g. Afsender vs Oprindelig afsender both map to
      // counterparty_name).
      if (field && !(fields[field]?.trim())) fields[field] = parsed.values[idx] ?? "";
    });

    rows.push({
      transactionDate: normalizeDateWithOrder(fields.transaction_date, profile.dateOrder) ?? "",
      bookingDate: normalizeDateWithOrder(fields.booking_date, profile.dateOrder),
      text: fields.text ?? "",
      amount: parseLocalizedNumber(fields.amount) ?? NaN,
      currency: normalizeCurrency(fields.currency),
      reference: fields.reference || undefined,
      amountDkk: parseLocalizedNumber(fields.amount_dkk),
      fxRateToDkk: parseLocalizedNumber(fields.fx_rate_to_dkk),
      counterpartyName: fields.counterparty_name || undefined,
      counterpartyAccount: fields.counterparty_account || undefined,
      message: fields.message || undefined,
      archiveReference: fields.archive_reference || undefined,
      customerReference: fields.customer_reference || undefined,
      balanceAfter: parseLocalizedNumber(fields.balance_after),
      raw,
    });
  }
  return { rows, errors };
}

export function validateBankImportRows(rows: BankImportRow[]) {
  const errors: string[] = [];
  let needsFxRule = false;
  rows.forEach((row, idx) => {
    if (!looksLikeIsoDate(row.transactionDate)) errors.push(`rows[${idx}].transactionDate must be YYYY-MM-DD`);
    if (row.bookingDate && !looksLikeIsoDate(row.bookingDate)) errors.push(`rows[${idx}].bookingDate must be YYYY-MM-DD when present`);
    if (typeof row.text !== "string" || row.text.trim().length === 0) errors.push(`rows[${idx}].text is required`);
    if (!Number.isFinite(normalizeAmount(row.amount))) errors.push(`rows[${idx}].amount must be numeric`);

    const currency = normalizeCurrency(row.currency);
    if (currency.length !== 3) errors.push(`rows[${idx}].currency must be a 3-letter ISO currency code`);
    if (currency !== "DKK") {
      needsFxRule = true;
      if (!Number.isFinite(normalizeAmount(row.amountDkk))) errors.push(`rows[${idx}].amountDkk is required for non-DKK rows`);
      if (!Number.isFinite(roundRate6(Number(row.fxRateToDkk))) || (row.fxRateToDkk ?? 0) <= 0) errors.push(`rows[${idx}].fxRateToDkk must be positive for non-DKK rows`);
      if (Number.isFinite(normalizeAmount(row.amountDkk)) && Number.isFinite(Number(row.fxRateToDkk))) {
        const expectedAmountDkk = multiplyDkk(row.amount ?? 0, row.fxRateToDkk ?? 0);
        if (compareDkk(normalizeAmount(row.amountDkk), expectedAmountDkk) !== 0) {
          errors.push(`rows[${idx}].amountDkk must equal amount * fxRateToDkk (${expectedAmountDkk})`);
        }
      }
    }
  });
  return { ok: errors.length === 0, appliedRules: needsFxRule ? [RULE_ID, FX_RULE_ID] : [RULE_ID], errors };
}

function transactionFingerprint(row: BankImportRow, occurrence: number, bankAccountId: number | null) {
  return sha256Bytes(JSON.stringify({
    bank_account_id: bankAccountId,
    transaction_date: row.transactionDate,
    booking_date: row.bookingDate ?? null,
    text: row.text.trim(),
    amount: normalizeAmount(row.amount),
    currency: normalizeCurrency(row.currency),
    reference: row.reference ?? null,
    amount_dkk: normalizeAmountOrNull(row.amountDkk),
    fx_rate_to_dkk: row.fxRateToDkk == null ? null : roundRate6(row.fxRateToDkk),
    occurrence,
  }));
}

function verifyBatchBalanceContinuity(db: Database, importedRowIds: number[]): BalanceContinuityResult {
  if (importedRowIds.length === 0) return {};
  const placeholders = importedRowIds.map(() => "?").join(", ");
  const rows = db.query(
    `SELECT id, transaction_date, text, amount, balance_after
     FROM bank_transactions
     WHERE id IN (${placeholders})
     ORDER BY transaction_date ASC, id ASC`,
  ).all(...importedRowIds) as BalanceRow[];

  const rowsWithBalance = rows.filter((row) => row.balance_after !== null && row.balance_after !== undefined);
  if (rowsWithBalance.length < 2) {
    // 0 rows: nothing to report. 1 row: a single balance, no adjacency to check.
    return rowsWithBalance.length === 1
      ? { firstBalance: roundDkk(Number(rowsWithBalance[0].balance_after)), lastBalance: roundDkk(Number(rowsWithBalance[0].balance_after)) }
      : {};
  }

  // Reconstruct true intra-day order before the walk (#191). The DB query
  // returns rows in (transaction_date, id) order; `id` is insertion order =
  // file order, which is reversed within a date for a newest-first export.
  // Each date's rows are re-chained from `balance_after`, carrying the running
  // balance across date boundaries.
  const withBalance: BalanceRow[] = [];
  let clusterStart = 0;
  while (clusterStart < rowsWithBalance.length) {
    let clusterEnd = clusterStart + 1;
    while (
      clusterEnd < rowsWithBalance.length &&
      rowsWithBalance[clusterEnd].transaction_date === rowsWithBalance[clusterStart].transaction_date
    ) {
      clusterEnd += 1;
    }
    const cluster = rowsWithBalance.slice(clusterStart, clusterEnd);
    const incoming = withBalance.length > 0 ? Number(withBalance[withBalance.length - 1].balance_after) : null;
    withBalance.push(...orderDayCluster(cluster, incoming));
    clusterStart = clusterEnd;
  }

  const balanceWarnings: string[] = [];
  for (let idx = 1; idx < withBalance.length; idx += 1) {
    const prev = withBalance[idx - 1];
    const curr = withBalance[idx];
    const expected = addDkk(Number(prev.balance_after), Number(curr.amount));
    if (!equalsDkk(expected, Number(curr.balance_after))) {
      const drift = subtractDkk(Number(curr.balance_after), expected);
      const warning =
        `balance break before bank transaction ${curr.id} (${curr.transaction_date} '${curr.text.trim()}'): ` +
        `expected ${expected} from previous balance ${roundDkk(Number(prev.balance_after))} + amount ${roundDkk(Number(curr.amount))}, ` +
        `statement shows ${roundDkk(Number(curr.balance_after))} (drift ${drift})`;
      balanceWarnings.push(warning);
      recordException(db, {
        type: "BANK_BALANCE_GAP",
        severity: "medium",
        relatedBankTransactionId: curr.id,
        message: warning,
        requiredAction: "Check the statement for missing, duplicated or misordered rows around this transaction; re-import the complete export if needed.",
        sourceEvidence: {
          ruleId: BALANCE_CONTINUITY_RULE_ID,
          bankTransactionId: curr.id,
          transactionDate: curr.transaction_date,
          previousBalance: roundDkk(Number(prev.balance_after)),
          amount: roundDkk(Number(curr.amount)),
          expectedBalance: expected,
          statementBalance: roundDkk(Number(curr.balance_after)),
          drift,
        },
      });
    }
  }

  return {
    balanceWarnings,
    firstBalance: roundDkk(Number(withBalance[0].balance_after)),
    lastBalance: roundDkk(Number(withBalance[withBalance.length - 1].balance_after)),
  };
}

function normalizeHeader(value: string) {
  return value
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, "_");
}

function detectDelimiter(headerLine: string) {
  const candidates = [",", ";", "\t"];
  return candidates
    .map((delimiter) => ({ delimiter, count: countDelimiterOutsideQuotes(headerLine, delimiter) }))
    .sort((a, b) => b.count - a.count)[0]?.delimiter ?? ",";
}

function parseCsvLine(line: string, delimiter: string) {
  const values: string[] = [];
  let current = "";
  let inQuotes = false;
  for (let idx = 0; idx < line.length; idx += 1) {
    const char = line[idx];
    if (char === '"') {
      if (inQuotes && line[idx + 1] === '"') {
        current += '"';
        idx += 1;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (!inQuotes && char === delimiter) {
      values.push(current.trim());
      current = "";
    } else {
      current += char;
    }
  }
  values.push(current.trim());
  return { values, unterminatedQuote: inQuotes };
}

function tokenizeLogicalCsvRecords(content: string): LogicalCsvRecord[] {
  const physicalLines = content
    .replace(/^\uFEFF/, "")
    .replace(/\r\n?/g, "\n")
    .split("\n");
  const records: LogicalCsvRecord[] = [];
  let recordLines: string[] = [];
  let startLine = 1;
  let inQuotes = false;

  for (const [lineIndex, line] of physicalLines.entries()) {
    if (recordLines.length === 0 && line.trim().length === 0) continue;
    if (recordLines.length === 0) startLine = lineIndex + 1;
    recordLines.push(line);

    for (let idx = 0; idx < line.length; idx += 1) {
      if (line[idx] !== '"') continue;
      if (inQuotes && line[idx + 1] === '"') idx += 1;
      else inQuotes = !inQuotes;
    }

    if (!inQuotes) {
      records.push({ text: recordLines.join("\n"), startLine });
      recordLines = [];
    }
  }

  if (recordLines.length > 0) {
    records.push({ text: recordLines.join("\n"), startLine });
  }
  return records;
}

function parseLocalizedNumber(value: string | undefined) {
  if (!value) return undefined;
  let trimmed = value.trim();
  if (!trimmed) return undefined;
  // Strip a trailing 3-letter ISO currency code that is whitespace-separated
  // from the number (e.g. "1234,56 DKK"). The whitespace requirement avoids
  // mangling garbage like "0xff" into a plausible amount.
  trimmed = trimmed.replace(/\s+[A-Za-z]{3}$/, "").trim();
  // Surrounding parentheses denote a negative amount in many bank exports.
  let sign = "";
  const paren = /^\((.*)\)$/.exec(trimmed);
  if (paren) {
    sign = "-";
    trimmed = paren[1].trim();
  }
  // Some Danish bank exports encode debits as a trailing minus. It is only
  // accepted when no other sign notation is present; conflicting forms such
  // as -123-, +123- and (123)- remain invalid.
  if (trimmed.endsWith("-")) {
    if (sign) return NaN;
    trimmed = trimmed.slice(0, -1).trim();
    if (/^[+-]/.test(trimmed.replace(/\s/g, ""))) return NaN;
    sign = "-";
  }
  const compact = trimmed.replace(/\s/g, "");

  let normalized: string;
  if (compact.includes(",")) {
    // Comma present: comma is the decimal separator, dots are thousands.
    if (!/^[+-]?(?:\d{1,3}(?:\.\d{3})+|\d+),\d+$/.test(compact)) {
      return NaN;
    }
    normalized = compact.replace(/\./g, "").replace(",", ".");
  } else if (/^[+-]?\d+(\.\d{3})+$/.test(compact)) {
    // Only digits and dots, every dot followed by exactly 3 digits and no
    // comma => Danish thousands grouping (e.g. "1.234" => 1234, "1.234.567").
    normalized = compact.replace(/\./g, "");
  } else {
    // Otherwise treat a single dot as a decimal point ("1234.56", "1234").
    normalized = compact;
  }

  normalized = sign + normalized;
  if (!STRICT_NUMERIC.test(normalized)) return NaN;
  return Number(normalized);
}

function normalizeDateWithOrder(value: string | undefined, order: BankImportProfile["dateOrder"]) {
  const trimmed = value?.trim();
  if (!trimmed) return undefined;
  if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return trimmed;
  if (order === "iso") return trimmed;
  const ymd = /^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/.exec(trimmed);
  if (order === "ymd" && ymd) {
    return `${ymd[1]}-${ymd[2].padStart(2, "0")}-${ymd[3].padStart(2, "0")}`;
  }
  const dmyMatch = /^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$/.exec(trimmed);
  if (!dmyMatch) return trimmed;
  const a = dmyMatch[1].padStart(2, "0");
  const b = dmyMatch[2].padStart(2, "0");
  const year = dmyMatch[3];
  if (order === "mdy") return `${year}-${a}-${b}`;
  // dmy (default for non-ISO)
  return `${year}-${b}-${a}`;
}

function decodeForProfile(bytes: Uint8Array, encoding: BankImportProfile["encoding"]) {
  if (encoding === "windows-1252") {
    return new TextDecoder("windows-1252").decode(bytes);
  }
  const utf8 = new TextDecoder("utf-8").decode(bytes);
  if (utf8.includes("�")) {
    return new TextDecoder("windows-1252").decode(bytes);
  }
  return utf8;
}

function orderDayCluster(cluster: BalanceRow[], incoming: number | null): BalanceRow[] {
  if (cluster.length < 2) return cluster;

  const remaining = [...cluster];
  const ordered: BalanceRow[] = [];

  // For the first cluster there is no carried-in balance; the start row is the
  // one whose pre-transaction balance matches no other row's balance_after.
  let running = incoming;
  if (running === null) {
    const balancesAfter = cluster.map((row) => Number(row.balance_after));
    const start = cluster.find(
      (row) => !balancesAfter.some((bal) => equalsDkk(bal, subtractDkk(Number(row.balance_after), Number(row.amount)))),
    );
    if (!start) return cluster;
    running = subtractDkk(Number(start.balance_after), Number(start.amount));
  }

  while (remaining.length > 0) {
    const nextIdx = remaining.findIndex(
      (row) => equalsDkk(subtractDkk(Number(row.balance_after), Number(row.amount)), running as number),
    );
    if (nextIdx === -1) return cluster; // no clean chain: keep insertion order
    const [next] = remaining.splice(nextIdx, 1);
    ordered.push(next);
    running = Number(next.balance_after);
  }
  return ordered;
}

function countDelimiterOutsideQuotes(line: string, delimiter: string) {
  let count = 0;
  let inQuotes = false;
  for (let idx = 0; idx < line.length; idx += 1) {
    const char = line[idx];
    if (char === '"') {
      if (inQuotes && line[idx + 1] === '"') idx += 1;
      else inQuotes = !inQuotes;
    } else if (!inQuotes && char === delimiter) {
      count += 1;
    }
  }
  return count;
}

export function recordException(db: Database, input: RecordExceptionInput) {
  const errors: string[] = [];
  const severity = input.severity ?? "medium";
  if (!["low", "medium", "high"].includes(severity)) errors.push("severity must be low, medium, or high");
  if (!input.type?.trim()) errors.push("type is required");
  if (!input.message?.trim()) errors.push("message is required");
  if (errors.length > 0) return { ok: false, exceptionId: undefined, duplicate: false, errors };

  const message = input.message.trim();
  const requiredAction = input.requiredAction?.trim() || null;
  const sourceEvidence = serializeJson(input.sourceEvidence);
  const postingPreview = serializeJson(input.postingPreview);
  const resolutionKey = input.resolutionKey?.trim() || null;

  const existing = db.query(
    `SELECT id
     FROM exceptions
     WHERE status = 'open'
       AND (resolution_key = ? OR (resolution_key IS NULL AND ? IS NULL))
       AND type = ?
       AND COALESCE(related_bank_transaction_id, 0) = COALESCE(?, 0)
       AND COALESCE(related_document_id, 0) = COALESCE(?, 0)
       AND message = ?
       AND COALESCE(required_action, '') = COALESCE(?, '')
     LIMIT 1`
  ).get(
    resolutionKey,
    resolutionKey,
    input.type.trim(),
    input.relatedBankTransactionId ?? null,
    input.relatedDocumentId ?? null,
    message,
    requiredAction,
  ) as { id: number } | null;

  if (existing) return { ok: true, exceptionId: existing.id, duplicate: true, errors: [] };

  const row = db.query(
    `INSERT INTO exceptions (
      type, severity, status, related_bank_transaction_id, related_document_id,
      message, required_action, source_evidence, posting_preview, resolution_key
    ) VALUES (?, ?, 'open', ?, ?, ?, ?, ?, ?, ?)
    RETURNING id`
  ).get(
    input.type.trim(),
    severity,
    input.relatedBankTransactionId ?? null,
    input.relatedDocumentId ?? null,
    message,
    requiredAction,
    sourceEvidence,
    postingPreview,
    resolutionKey,
  ) as { id: number };

  return { ok: true, exceptionId: row.id, duplicate: false, errors: [] };
}

export function resolveException(db: Database, input: ResolveExceptionInput) {
  const errors: string[] = [];
  if (!Number.isInteger(input.id) || input.id <= 0) errors.push("id must be a positive integer");
  if (errors.length > 0) return { ok: false, resolved: false, errors };

  const row = db.query(`SELECT id, status FROM exceptions WHERE id = ? LIMIT 1`).get(input.id) as { id: number; status: string } | null;
  if (!row) return { ok: false, resolved: false, errors: [`exception ${input.id} does not exist`] };
  if (row.status === "resolved") return { ok: true, resolved: false, errors: [] };

  runSql(db,
    `UPDATE exceptions
     SET status = 'resolved', resolved_at = CURRENT_TIMESTAMP, resolved_by = ?, resolution_note = ?
     WHERE id = ?`,
    input.resolvedBy ?? null,
    input.note?.trim() || null,
    input.id,
  );

  return { ok: true, resolved: true, errors: [] };
}

function findCandidateBilag(db: Database, bankTransactionId: number, amount: number): CandidateBilag | null {
  if (!(Math.abs(amount) > 0)) return null;
  // Round to integer øre to compare a raw float bank amount against the
  // document gross safely (matches the comparison the matcher uses).
  const ore = Math.round(Math.abs(amount) * 100);
  const rows = db
    .query(
      `SELECT d.id, d.document_no, d.document_type, d.supplier_name, d.delivery_description
       FROM documents d
       LEFT JOIN journal_entries je ON je.document_id = d.id AND je.status = 'posted'
       WHERE d.document_type IN ('purchase_sale', 'cash_register_receipt')
         AND je.id IS NULL
         AND CAST(ROUND(d.amount_inc_vat * 100) AS INTEGER) = ?
       LIMIT 2`,
    )
    .all(ore) as Array<{
      id: number;
      document_no: string | null;
      document_type: string;
      supplier_name: string | null;
      delivery_description: string | null;
    }>;
  if (rows.length !== 1) return null;
  const row = rows[0]!;
  return {
    documentId: row.id,
    documentNo: row.document_no,
    documentType: row.document_type,
    supplierName: row.supplier_name,
    deliveryDescription: row.delivery_description,
  };
}

function describeUnmatchedBankTransaction(
  bank: { id: number; transaction_date: string; text: string | null; amount: number; currency: string },
  bilag: CandidateBilag | null,
): { message: string; requiredAction: string } {
  const beløb = formatBankAmount(bank.amount, bank.currency);
  const tekst = (bank.text ?? "").trim() || "(ingen tekst)";
  const direction = bankDirection(bank.amount);
  // Sign-aware nouns: an inbound payment is income (an "indbetaling"), an
  // outbound one an expense (a "betaling"/"udgift"). #237: a money-in line
  // must never be described as a deductible expense.
  const kindNoun = direction === "income" ? "indbetalingen" : "betalingen";
  const linje =
    direction === "income"
      ? `Indbetalingen "${tekst}" den ${bank.transaction_date} på ${beløb} er endnu ikke bogført`
      : `Banktransaktionen "${tekst}" den ${bank.transaction_date} på ${beløb} er endnu ikke bogført`;

  // No bilag at all — the owner is missing the underlying voucher.
  if (!bilag) {
    if (direction === "income") {
      return {
        message:
          `${linje}. Der er ikke fundet et bilag (faktura eller anden indtægtsdokumentation), ` +
          `der passer til beløbet.`,
        requiredAction:
          "Find fakturaen eller dokumentationen for denne indbetaling og læg den i bogføringen. " +
          "Uden et bilag kan indtægten ikke bogføres korrekt, og evt. salgsmoms kan ikke afregnes.",
      };
    }
    return {
      message: `${linje}. Der er ikke fundet et bilag (kvittering eller faktura), der passer til beløbet.`,
      requiredAction:
        "Find kvitteringen eller fakturaen for denne betaling og læg den i bogføringen. " +
        "Uden et bilag kan udgiften ikke bogføres og momsen ikke fratrækkes.",
    };
  }

  const bilagNavn = bilag.documentNo ? `bilag ${bilag.documentNo}` : `et bilag (id ${bilag.documentId})`;
  const leverandør = bilag.supplierName ? ` fra ${bilag.supplierName}` : "";

  // Representation / restaurant voucher missing its purpose + attendees — the
  // exact case from the README: "Restaurantbilag mangler formål og deltagere".
  // Representation is by definition an outbound expense; the wording stays
  // expense-shaped here regardless of any odd sign.
  if (looksLikeRepresentation(bilag, tekst)) {
    return {
      message:
        `${linje}. Den passer til ${bilagNavn}${leverandør}, som ligner et restaurant-/bevirtningsbilag. ` +
        `Bilaget mangler formål og deltagere — det skal fremgå, hvem der deltog, og hvad anledningen var.`,
      requiredAction:
        "Skriv formålet med bevirtningen og navnene på deltagerne på bilaget (fx \"kundemøde, " +
        "Anders Jensen, Acme A/S\"). Formål og deltagere er et lovkrav for, at udgiften kan " +
        "fradrages som repræsentation. Bogfør derefter bilaget mod betalingen.",
    };
  }

  // A matching bilag exists but the link is not yet posted. #237: do NOT
  // claim "no bilag found" here — name the real reason it still needs
  // attention (the bilag is not yet booked against the bank line) and keep
  // the income/expense wording aligned with the amount's sign.
  if (direction === "income") {
    return {
      message:
        `${linje}. Den passer til ${bilagNavn}${leverandør}, men bilaget er endnu ikke bogført mod indbetalingen.`,
      requiredAction:
        `Kontroller, at ${bilagNavn} hører til denne indbetaling, og bogfør indtægten mod banktransaktionen.`,
    };
  }
  return {
    message:
      `${linje}. Den passer til ${bilagNavn}${leverandør}, men bilaget er endnu ikke bogført mod ${kindNoun}.`,
    requiredAction:
      `Kontroller, at ${bilagNavn} hører til denne betaling, og bogfør udgiften mod banktransaktionen.`,
  };
}

function serializeJson(value: unknown) {
  if (value === undefined) return null;
  return JSON.stringify(value);
}

function looksLikeRepresentation(bilag: CandidateBilag, bankText: string): boolean {
  const haystack = [
    bilag.documentType,
    bilag.supplierName ?? "",
    bilag.deliveryDescription ?? "",
    bankText,
  ]
    .join(" ")
    .toLowerCase();
  if (bilag.documentType === "cash_register_receipt") return true;
  return /restaurant|café|cafe|bistro|kro|brasserie|brasseri|spisehus|diner|bevirtning|frokost|middag/.test(
    haystack,
  );
}

function formatBankAmount(amount: number, currency: string | null | undefined): string {
  if (normalizeCurrency(currency) === "DKK") return formatKronerDa(Math.abs(amount));
  const formatted = Math.abs(amount).toLocaleString("da-DK", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  return `${formatted} ${normalizeCurrency(currency)}`;
}

function bankDirection(amount: number): BankDirection {
  return amount > 0 ? "income" : "expense";
}

export function retryTransientCleanup<T>(operation: () => T, options: CleanupRetryOptions = {}): T {
  const maxAttempts = options.maxAttempts ?? DEFAULT_BACKOFF_MS.length + 1;
  const sleep = options.sleep ?? defaultSleep;
  for (let attempt = 1; ; attempt += 1) {
    try {
      return operation();
    } catch (error) {
      if (!isTransientWindowsCleanupError(error) || attempt >= maxAttempts) throw error;
      sleep(DEFAULT_BACKOFF_MS[Math.min(attempt - 1, DEFAULT_BACKOFF_MS.length - 1)]!);
    }
  }
}

function isTransientWindowsCleanupError(error: unknown): boolean {
  return Boolean(
    error && typeof error === "object" && "code" in error &&
      typeof error.code === "string" && TRANSIENT_WINDOWS_CLEANUP_CODES.has(error.code),
  );
}

