export function planCurrentPdfParses(db: Database, options: { limit?: number; cursor?: number } = {}) {
  const limit=options.limit ?? 100, cursor=options.cursor ?? 0;
  if (!Number.isInteger(limit) || limit < 1 || limit > 100 || !Number.isInteger(cursor) || cursor < 0) throw new Error("PDF parser cursor/limit is invalid");
  const rows=db.query(`SELECT d.id FROM documents d WHERE d.id>? AND d.mime_type='application/pdf' AND d.stored_path IS NOT NULL AND d.sha256_hash IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document_pdf_parse_results p WHERE p.document_id=d.id AND p.source_sha256_hash=d.sha256_hash AND p.parser_id=? AND p.parser_version=? AND p.contract_version=?) ORDER BY d.id LIMIT ?`).all(cursor,PDF_PARSER_ID,PDF_PARSER_VERSION,PDF_PARSER_CONTRACT_VERSION,limit) as Array<{id:number}>;
  return { documentIds: rows.map(r=>r.id), cursor, nextCursor: rows.length === limit ? rows.at(-1)!.id : null };
}

