coreBehaviorDefinitions.typescript:
export function loadDigisenseSecretConfig(
  companyRoot: string,
): DigisenseSecretConfig | null {
  const path = digisenseConfigPath(companyRoot);
  if (!existsSync(path)) return null;
  const raw = readFileSync(path, "utf8");
  return JSON.parse(raw) as DigisenseSecretConfig;
}

export async function onboardDigisenseCompany(
  db: Database, companyRoot: string, client: DigisenseClient, actor?: ResolveActorInput,
): Promise<{ ok: true; status: DigisenseOnboardingStatus; companyKey: string } | { ok: false; errors: string[]; status: DigisenseOnboardingStatus }> {
  const before = getDigisenseOnboardingStatus(db, companyRoot);
  if (!before.identity) return { ok: false, errors: before.blockers, status: before };
  const auth = await client.validateAuth();
  if (!auth.ok) return { ok: false, errors: [`validate-auth failed: ${auth.error.message}`], status: before };
  const result = await registerDigisenseCompany(db, companyRoot, client, {
    companyType: { type: "DK:CVR", id: before.identity.cvr }, companyName: before.identity.companyName,
    actor,
  });
  const status = getDigisenseOnboardingStatus(db, companyRoot);
  return result.ok ? { ok: true, status, companyKey: result.companyKey } : { ok: false, errors: result.errors, status };
}

export function createDigisenseClient(
  config: DigisenseClientConfig,
  deps: DigisenseClientDeps = {},
): DigisenseClient {
  if (!config.apiLicenseKey?.trim()) {
    throw new Error("digisense client: apiLicenseKey is required");
  }
  const baseUrl = digisenseBaseUrl(config.environment);
  const httpFetch = deps.fetch ?? defaultHttpFetch();

  // Fælles headers. Authorization bærer license-key'en (én nøgle pr. licens).
  function authHeaders(contentType?: string): Record<string, string> {
    const headers: Record<string, string> = {
      Authorization: config.apiLicenseKey,
      Accept: "application/json",
    };
    if (contentType) headers["Content-Type"] = contentType;
    return headers;
  }

  // Udfør et kald og parse JSON-svaret. Ikke-2xx mappes til en tydelig
  // DigisenseError; transport-/parse-fejl bliver status 0 så kaldere altid får
  // et Result i stedet for en throw der lækker stack-traces til envelopen.
  async function requestJson<T>(request: HttpRequest): Promise<DigisenseResult<T>> {
    let response: HttpResponse;
    try {
      response = await httpFetch(request);
    } catch (error) {
      return {
        ok: false,
        error: {
          status: 0,
          message: `digisense transport error: ${error instanceof Error ? error.message : String(error)}`,
        },
      };
    }

    const rawBody = await response.text();

    if (response.status < 200 || response.status >= 300) {
      return {
        ok: false,
        error: {
          status: response.status,
          message: `digisense responded ${response.status}`,
          body: rawBody,
        },
      };
    }

    if (rawBody.trim().length === 0) {
      // Tomt 2xx-svar => tomt objekt (fx endpoints der kun signalerer succes).
      return { ok: true, status: response.status, data: {} as T };
    }

    try {
      return { ok: true, status: response.status, data: JSON.parse(rawBody) as T };
    } catch (error) {
      return {
        ok: false,
        error: {
          status: response.status,
          message: `digisense returned unparseable JSON: ${error instanceof Error ? error.message : String(error)}`,
          body: rawBody,
        },
      };
    }
  }

  return {
    validateAuth() {
      return requestJson<ValidateAuthResponse>({
        method: "GET",
        url: `${baseUrl}/validate-auth`,
        headers: authHeaders(),
      });
    },

    registerCompany(body) {
      return requestJson<RegisterCompanyResponse>({
        method: "POST",
        url: `${baseUrl}/register-company`,
        headers: authHeaders("application/json"),
        body: JSON.stringify(body),
      });
    },

    registerParticipant(network, body) {
      return requestJson<RegisterParticipantResponse>({
        method: "POST",
        // v1 is deprecated. v2 remains under the configured REST base URL.
        url: `${baseUrl}/v2/register-participant/${network}`,
        headers: authHeaders("application/json"),
        body: JSON.stringify(body),
      });
    },

    validateDocument(xml) {
      // Schematron-validering: XML-body som string, application/xml.
      return requestJson<ValidateDocumentResponse>({
        method: "POST",
        url: `${baseUrl}/validate-document`,
        headers: authHeaders("application/xml"),
        body: xml,
      });
    },

    lookupParticipant(query) {
      return requestJson<LookupParticipantResponse>({
        method: "GET",
        url: `${baseUrl}/lookup-participant${buildQuery({
          networkType: query.networkType,
          documentType: query.documentType,
          participantScheme: query.participantScheme,
          participantValue: query.participantValue,
        })}`,
        headers: authHeaders(),
      });
    },

    deliverDocument(xml, query) {
      // XML-faktura (<=10MB). companyKey + valgfrit ksefEnvironment i query.
      return requestJson<DeliverDocumentResponse>({
        method: "POST",
        url: `${baseUrl}/deliver-document${buildQuery({
          companyKey: query.companyKey,
          ksefEnvironment: query.ksefEnvironment,
        })}`,
        headers: authHeaders("application/xml"),
        body: xml,
      });
    },

    documentStatus(documentId, companyKey) {
      return requestJson<DocumentStatusResponse>({
        method: "GET",
        url: `${baseUrl}/document-status/${encodeURIComponent(documentId)}${buildQuery({ companyKey })}`,
        headers: authHeaders(),
      });
    },

    listReceivedDocuments(query) {
      return requestJson<ListReceivedDocumentsResponse>({
        method: "GET",
        url: `${baseUrl}/list-received-documents${buildQuery({
          limit: query.limit,
          offset: query.offset,
          maxTimestamp: query.maxTimestamp,
          companyKey: query.companyKey,
          networkType: query.networkType,
          participantType: query.participantType,
          participantId: query.participantId,
        })}`,
        headers: authHeaders(),
      });
    },
  };
}

transitiveLocalBehaviorDefinitions.typescript:
function digisenseConfigPath(companyRoot: string): string {
  return join(companyRoot, "config", "digisense.json");
}

export function getDigisenseOnboardingStatus(db: Database, companyRoot: string): DigisenseOnboardingStatus {
  const config = loadDigisenseSecretConfig(companyRoot);
  const identity = resolveDigisenseIdentity(db);
  const blockers: string[] = [];
  if (!config) blockers.push("Digisense API credentials are not configured.");
  if (!identity.ok) blockers.push(...identity.errors);
  const key = identity.ok ? resolveBoundDigisenseCompanyKey(db) : null;
  if (identity.ok && (!key || !key.ok)) blockers.push(...(key?.ok === false ? key.errors : []));
  const participants = key?.ok ? listDigisenseParticipants(db, key.value) : [];
  // Readiness is a complete routing pair for the ledger identity on ONE
  // network. A stale GLN, another CVR, or directions split across networks is
  // not a send/receive-ready company.
  const matching = identity.ok
    ? participants.filter((p) => p.participantType === "DK:CVR" && p.participantId === identity.value.cvr && p.registeredOnNetwork)
    : [];
  const readyNetwork = ["nemhandel", "peppol"].find((network) =>
    matching.some((p) => p.network === network && p.direction === "inbound") &&
    matching.some((p) => p.network === network && p.direction === "outbound"),
  );
  const inboundReady = Boolean(readyNetwork);
  const outboundReady = Boolean(readyNetwork);
  if (key?.ok && !inboundReady) blockers.push("Inbound participant is not registered.");
  if (key?.ok && !outboundReady) blockers.push("Outbound participant is not registered.");
  return { configured: Boolean(config), environment: config?.environment ?? null, identity: identity.ok ? identity.value : null, companyKeyConfigured: Boolean(key?.ok), inboundReady, outboundReady, ready: blockers.length === 0, blockers };
}

export function digisenseBaseUrl(environment: DigisenseEnvironment): string {
  return `${environment === "production" ? PRODUCTION_BASE_URL : TEST_BASE_URL}${BASE_PATH}`;
}

function defaultHttpFetch(): HttpFetch {
  return async (request) => {
    const response = await fetch(request.url, {
      method: request.method,
      headers: request.headers,
      body: request.body,
    });
    return {
      status: response.status,
      text: () => response.text(),
    };
  };
}

function buildQuery(params: Record<string, unknown>): string {
  const pairs: string[] = [];
  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null || value === "") continue;
    pairs.push(`${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`);
  }
  return pairs.length > 0 ? `?${pairs.join("&")}` : "";
}

