export function listWorkspaceCompanies(workspaceRoot: string): WorkspaceCompanyEntry[] {
  return loadWorkspaceManifest(workspaceRoot).companies;
}

export function companyRootForSlug(workspaceRoot: string, slug: string): string {
  assertValidSlug(slug);
  return join(workspaceRoot, slug);
}

localBehaviorDefinitions.typescript:
function resolvePortfolioWorkspace(raw?: string): { ok: true; root: string } | { ok: false; error: string } {
  const trimmed = typeof raw === "string" ? raw.trim() : "";
  try {
    if (trimmed.length > 0) {
      return { ok: true, root: resolveWorkspaceRoot(trimmed) };
    }
    const configured = resolveConfiguredWorkspaceRoot();
    if (!configured) {
      return {
        ok: false,
        error: "no workspace given: pass 'workspace' or set RENTEMESTER_WORKSPACE",
      };
    }
    return { ok: true, root: configured };
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error.message : String(error) };
  }
}

function todayIsoDate(): string {
  const now = new Date();
  const y = now.getUTCFullYear();
  const m = String(now.getUTCMonth() + 1).padStart(2, "0");
  const d = String(now.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function companyStatusRow(
  slug: string,
  registeredName: string,
  companyRoot: string,
  asOfDate: string,
): Record<string, unknown> {
  const base = { slug, name: registeredName };
  const dbPath = companyPaths(companyRoot).db;
  if (!existsSync(dbPath)) {
    return { ...base, ok: false, error: "company ledger not found on disk" };
  }
  const db = openLedgerReadOnly(dbPath);
  try {
    const schema = inspectOpenLedger(db);
    if (schema.status !== "current") {
      return { ...base, ok: false, error: `schema_${schema.status}` };
    }
    const settings = getCompanySettings(db);
    // The VAT period window follows the company's real SKAT cadence
    // (`vatPeriodType`) — a monthly filer gets a one-month window, a
    // half-yearly filer a six-month one. `core/periods.ts` owns the math.
    // A non-registered company has no VAT period — surface a sentinel so
    // the portfolio JSON consumer can branch on `vatRegistered: false`
    // instead of reading an invented period.
    const vatPeriodType = settings.vatPeriodType;
    const vatBlock =
      vatPeriodType === null
        ? {
            vatRegistered: false as const,
            periodStart: null,
            periodEnd: null,
            daysUntilDue: null,
            netVatPayable: null,
            canCompute: false,
          }
        : (() => {
            const period = vatPeriodWindowFor(asOfDate, vatPeriodType);
            const vat = buildVatReport(db, period.start, period.end);
            return {
              vatRegistered: true as const,
              periodStart: period.start,
              periodEnd: period.end,
              daysUntilDue: daysBetween(asOfDate, period.end),
              netVatPayable: vat.ok ? vat.netVatPayable : null,
              canCompute: vat.ok,
            };
          })();
    const open = buildInvoiceList(db, { status: "open", asOfDate });
    const overdue = buildInvoiceList(db, { status: "overdue", asOfDate });
    const exceptions = listExceptions(db, { status: "open" });
    const backup = getBackupComplianceStatus(db, companyRoot, asOfDate);
    const audit = verifyAuditChain(db);
    const openReceivables = open.rows.reduce((acc, r) => acc + r.openBalance, 0);
    return {
      ...base,
      name: settings.name || registeredName,
      cvr: settings.cvr,
      ok: true,
      vat: vatBlock,
      openReceivables: {
        count: open.count,
        totalOpenBalance: openReceivables,
        overdueCount: overdue.count,
      },
      backup: {
        backupDue: backup.backupDue,
        daysSinceLatestBackup: backup.daysSinceLatestBackup,
        hasActivitySinceBackup: backup.hasActivitySinceBackup,
        backupsFound: backup.backupsFound,
      },
      audit: { ok: audit.ok, entries: audit.entries, firstError: audit.errors[0] ?? null },
      openExceptions: {
        count: exceptions.count,
        highSeverityCount: exceptions.rows.filter((r: { severity: string }) => r.severity === "high").length,
      },
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return { ...base, ok: false, error: redactPaths(message) };
  } finally {
    db.close();
  }
}

transitiveLocalBehaviorDefinitions.typescript:
function assertValidSlug(slug: string): void {
  if (!isValidSlug(slug)) {
    throw new Error(
      `invalid company slug '${slug}': use lowercase letters, digits and dashes`,
    );
  }
}

export function loadWorkspaceManifest(workspaceRoot: string): WorkspaceManifest {
  const path = manifestPath(workspaceRoot);
  if (!existsSync(path)) return emptyManifest();
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(path, "utf8"));
  } catch {
    throw new Error(`workspace manifest at ${path} is not valid JSON`);
  }
  if (!parsed || typeof parsed !== "object" || !Array.isArray((parsed as any).companies)) {
    throw new Error(`workspace manifest at ${path} is malformed`);
  }
  if ((parsed as any).version !== MANIFEST_VERSION) {
    throw new Error(
      `workspace manifest at ${path} has unsupported version ${(parsed as any).version}; expected ${MANIFEST_VERSION}`,
    );
  }
  const companies: WorkspaceCompanyEntry[] = (parsed as any).companies.map((raw: any) => ({
    slug: String(raw.slug),
    name: String(raw.name),
    createdAt: String(raw.createdAt),
    archived: Boolean(raw.archived),
  }));
  return { version: MANIFEST_VERSION, companies };
}

export function isValidSlug(slug: string): boolean {
  return /^[a-z0-9][a-z0-9-]*$/.test(slug);
}

function manifestPath(workspaceRoot: string): string {
  return join(workspaceRoot, WORKSPACE_MANIFEST_FILE);
}

function emptyManifest(): WorkspaceManifest {
  return { version: MANIFEST_VERSION, companies: [] };
}

