function acontoTaxDeadlinesForIncomeYear(fiscalYearEnd: string): AcontoTaxDeadline[] {
  const incomeYear = fiscalYearEnd.slice(0, 4);
  return [
    { installment: 1, dueDate: `${incomeYear}-03-20` },
    { installment: 2, dueDate: `${incomeYear}-11-20` },
  ];
}

