coreBehaviorDefinitions.typescript:
export function currentRuleBundleVersion() {
  return readRuleBundleMetadata()
    .map((bundle) => `${bundle.name}=${bundle.version}`)
    .join(";");
}

export function getBuildIdentity(
  env: NodeJS.ProcessEnv = process.env,
): BuildIdentity {
  if (!isValidSemVer(packageJson.version)) {
    throw new Error(`package.json contains invalid SemVer: ${packageJson.version}`);
  }

  const declaredVersion = optionalBuildValue(env.RENTEMESTER_VERSION);
  if (declaredVersion && declaredVersion !== packageJson.version) {
    throw new Error(
      `RENTEMESTER_VERSION ${declaredVersion} does not match packaged version ${packageJson.version}`,
    );
  }

  const gitCommit = optionalBuildValue(env.RENTEMESTER_GIT_COMMIT);
  if (gitCommit && !GIT_COMMIT_PATTERN.test(gitCommit)) {
    throw new Error("RENTEMESTER_GIT_COMMIT must be a 7-64 character hexadecimal commit id");
  }

  const builtAt = optionalBuildValue(env.RENTEMESTER_BUILT_AT);
  if (builtAt && Number.isNaN(Date.parse(builtAt))) {
    throw new Error("RENTEMESTER_BUILT_AT must be an ISO-8601 timestamp");
  }

  const bunVersion = optionalBuildValue(env.RENTEMESTER_BUN_VERSION);
  if (bunVersion && !isValidSemVer(bunVersion)) {
    throw new Error("RENTEMESTER_BUN_VERSION must be a SemVer version");
  }

  const baseImageDigest = optionalBuildValue(env.RENTEMESTER_BASE_IMAGE_DIGEST);
  if (baseImageDigest && !/^sha256:[0-9a-f]{64}$/i.test(baseImageDigest)) {
    throw new Error("RENTEMESTER_BASE_IMAGE_DIGEST must be a sha256 digest");
  }

  return {
    version: packageJson.version,
    gitCommit,
    builtAt,
    bunVersion,
    baseImageDigest,
  };
}

export function getReleaseProvenance(): ReleaseProvenance {
  return {
    product: getBuildIdentity(),
    schema: {
      version: CURRENT_SCHEMA_VERSION,
      baselineChecksum: BASELINE_MIGRATION_CHECKSUM,
    },
    rules: {
      digest: computeRuleSetDigest(),
    },
  };
}

export function catalogueIdentity() {
  let ruleBundleVersion: string | null = null;
  try { ruleBundleVersion = currentRuleBundleVersion(); } catch {}
  return { schemaVersion: AGENT_CATALOGUE_SCHEMA_VERSION, hash: AGENT_CATALOGUE_HASH, entryPoint: AGENT_CATALOGUE_ENTRY_POINT, capabilityCount: AGENT_CAPABILITIES.length, workflowCount: AGENT_WORKFLOWS.length, coverage: coverageIdentity(), build: getBuildIdentity(), provenance: getReleaseProvenance(), ruleBundleVersion };
}

transitiveLocalBehaviorDefinitions.typescript:
export function readRuleBundleMetadata(): RuleBundleMetadata[] {
  return readdirSync(rulesDir)
    .filter((file) => file.endsWith(".yaml"))
    .sort()
    .map((file) => {
      const path = join(rulesDir, file);
      const text = readFileSync(path, "utf8");
      return {
        name: file.replace(/\.yaml$/, ""),
        path,
        version: extractVersion(text, file),
        ruleIds: [...text.matchAll(/^\s*-\s*rule_id:\s*(\S+)$/gm)].map((match) => match[1]),
        sourceIds: [...text.matchAll(/^\s*source_id:\s*(\S+)$/gm)].map((match) => match[1]),
        declaredSources: extractSectionValues(text, "sources", /^\s*-\s*(DK-[A-Z0-9-]+)$/),
        vatCodes: extractSectionValues(text, "vat_codes", /^\s*-\s*code:\s*(\S+)$/),
      };
    });
}

function extractVersion(text: string, file: string) {
  const match = text.match(/^version:\s*(\S+)$/m);
  if (!match) throw new Error(`Missing version in ${file}`);
  return match[1];
}

function extractSectionValues(text: string, section: string, itemPattern: RegExp) {
  const values: string[] = [];
  let inSection = false;
  for (const line of text.split(/\r?\n/)) {
    if (/^[A-Za-z_]+:/.test(line)) {
      inSection = line.trim() === `${section}:`;
      continue;
    }
    if (!inSection) continue;
    const match = line.match(itemPattern);
    if (match) values.push(match[1]);
  }
  return values;
}

function optionalBuildValue(value: string | undefined): string | null {
  const trimmed = value?.trim();
  return trimmed ? trimmed : null;
}

export function computeRuleSetDigest(
  repositoryRoot: string = DEFAULT_REPOSITORY_ROOT,
): string {
  const root = resolve(repositoryRoot);
  if (root === resolve(DEFAULT_REPOSITORY_ROOT) && cachedDefaultDigest) {
    return cachedDefaultDigest;
  }
  const files = [
    ...listFilesRecursively(join(root, "rules", "dk")),
    ...listFilesRecursively(join(root, "sources")),
  ].sort((left, right) =>
    compareCodeUnits(
      relative(root, left).replaceAll("\\", "/"),
      relative(root, right).replaceAll("\\", "/"),
    ),
  );

  const hash = createHash("sha256");
  for (const path of files) {
    const portablePath = relative(root, path).replaceAll("\\", "/");
    const content = readFileSync(path);
    hash.update(portablePath, "utf8");
    hash.update("\0");
    hash.update(String(content.byteLength), "utf8");
    hash.update("\0");
    hash.update(content);
    hash.update("\0");
  }
  const digest = `sha256:${hash.digest("hex")}`;
  if (root === resolve(DEFAULT_REPOSITORY_ROOT)) cachedDefaultDigest = digest;
  return digest;
}

function listFilesRecursively(root: string): string[] {
  return readdirSync(root, { withFileTypes: true })
    .flatMap((entry) => {
      const path = join(root, entry.name);
      return entry.isDirectory() ? listFilesRecursively(path) : [path];
    })
    .filter((path) => statSync(path).isFile());
}

function compareCodeUnits(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

export function coverageIdentity() {
  return {
    schemaVersion: "rentemester-agent-discovery-coverage-v1" as const,
    rulesHash: AGENT_DISCOVERY_COVERAGE_RULES_HASH,
    surfaceBaselines: AGENT_SURFACE_BASELINES,
  };
}

