  db.query(`INSERT INTO posting_rule_lifecycle_events(rule_version_id,state,effective_at,actor,approver,rationale,provenance,expected_payload_hash,superseding_version_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)`)
